ƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬
  async function doImport() {
    if (!org) { toast('No organisation found.'); return; }
    setLoading(true);
    try {
      const payeeIds = {};
      for (const t of selectedRows) {
        const payeeName = autoCatMap[t._key]?.sugPayee;
        if (!payeeName || payeeIds[payeeName]) continue;
        const existing = (payees||[]).find(p => p.name.toLowerCase() === payeeName.toLowerCase());
        if (existing) {
          payeeIds[payeeName] = existing.id;
        } else {
          const col = (PALETTE||[])[Object.keys(payeeIds).length % (PALETTE||['#888']).length] || '#888';
          const created = await upsertPayee(org.id, payeeName, col);
          payeeIds[payeeName] = created.id;
          setPayees(prev => prev.find(p => p.id === created.id) ? prev : [...prev, created]);
        }
      }

      const toImport = selectedRows.map(t => {
        const sug = autoCatMap[t._key];
        const payeeName = sug?.sugPayee || '';
        return ({
          date:        t.date,
          desc:        t.desc,
          amt:         t.amt,
          cat:         sug?.sugCat || t.cat,
          payee_id:    payeeName ? payeeIds[payeeName] || null : null,
          note:        t.note,
          account_id:  selectedAccount || null,
        });
      });
      if (toImport.length === 0) { toast('No transactions selected.'); return; }
      const { inserted, linked, skipped } = await bulkImportTransactions(org.id, toImport);
      const parts = [`Imported ${inserted} transaction${inserted!==1?'s':''}`];
      if (linked)  parts.push(`${linked} existing linked to account`);
      if (skipped) parts.push(`${skipped} duplicates skipped`);

      // Detect new payees from rules
      const newPayeeNames = new Set();
      toImport.forEach(t => {
        const matchedRule = (rules||[]).find(r => t.desc?.toLowerCase().includes(r.keyword?.toLowerCase()) && r.payee);
        if (matchedRule?.payee) {
          const existing = (payees||[]).find(p => p.name.toLowerCase() === matchedRule.payee.toLowerCase());
          if (!existing) newPayeeNames.add(matchedRule.payee);
        }
      });
      if (newPayeeNames.size > 0) setNewPayeesFound([...newPayeeNames]);

      // Update bank account opening balance from earliest imported statement
      if (selectedAccount) {
        const summaries = parsedFiles.map(pf => pf.summary).filter(
          s => s && s.openingBalance != null && s.periodStart
        );
        if (summaries.length > 0) {
          const earliest = summaries.reduce((best, s) =>
            !best || s.periodStart < best.periodStart ? s : best, null
          );
          try {
            const acct = (accounts||[]).find(a => a.id === selectedAccount);
            if (acct && earliest && (!acct.opening_date || earliest.periodStart < acct.opening_date)) {
              const updated = await updateBankAccount(selectedAccount, {
                opening_balance: earliest.openingBalance,
                opening_date:    earliest.periodStart,
              });
              if (updated && setAccounts) {
                setAccounts(prev => prev.map(a => a.id===selectedAccount ? {...a,...updated} : a));
              }
              parts.push(`Opening balance updated to $${Math.abs(earliest.openingBalance).toFixed(2)}`);
            }
          } catch(e) { console.warn('Opening balance update failed:', e.message); }
        }
      }

      toast(parts.join(' ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â· ') + '.');

      const fresh = await getTransactions(org.id, '2000-01-01', '2099-12-31');
      const normalise = t => ({ ...t, cat:t.category_id??null, desc:t.description??'', amt:parseFloat(t.amount)??0, payee:t.payees?.name??t.payee??'', note:t.note??'' });
      setTxns(fresh.map(normalise));

      if (newPayeeNames.size === 0) onNavigate('transactions');
    } catch(e) { toast('Import failed: ' + e.message); }
    finally { setLoading(false); }
  }

